// Frontend JavaScript connecting to an SSE stream

// 1. Connect to the EventStream endpoint
const eventSource = new EventSource('https://api.com/live-scores');

// 2. Listen for data packets being streamed down
eventSource.onmessage = (event) => {
  const data = JSON.parse(event.data);
  console.log("New Score! ", data);
};

// 3. If the connection drops, EventSource automatically tries to reconnect!
eventSource.onerror = () => {
  console.log("Connection lost. Reconnecting...");
};
